category_id = #{categoryId}, name = #{name}, subtitle = #{subtitle}, main_image = #{mainImage}, price = #{price}, stock = #{stock}, detail = #{detail}, is_hot = #{isHot}, status = #{status},
WHERE id = #{id}

mapper.select:
SELECT p.*, c.name AS category_name
FROM product p LEFT JOIN category c ON p.category_id = c.id
WHERE p.id = #{id}

SELECT 
FROM product p LEFT JOIN category c ON p.category_id = c.id


        AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.subtitle LIKE CONCAT('%', #{keyword}, '%'))


        AND p.category_id = #{categoryId}


        AND p.status = #{status}


        AND p.is_hot = #{hot}



    ORDER BY p.price ASC
    ORDER BY p.price DESC
    ORDER BY p.sales DESC
    ORDER BY p.id DESC

